// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    StrictToken token;
    address owner;

    function setUp() public { address __invmut_eoa = address(uint160(0xE0A)); vm.deal(__invmut_eoa, 100 ether); vm.startPrank(__invmut_eoa, __invmut_eoa); c = new PoCGame(address(this), 0); vm.stopPrank(); owner = __invmut_eoa; token = new StrictToken(address(this)); }

    function testFuzz_property(address tokenOwner, uint256 tokens) public {
        vm.assume(tokenOwner != address(this));
        vm.assume(tokenOwner != address(token));
        vm.assume(tokenOwner != address(c));
        vm.prank(owner);
        bool ok = true;
        bool success = false;
        try c.transferAnyERC20Token(address(token), tokenOwner, tokens) returns (bool s) {
            ok = true;
            success = s;
        } catch {
            ok = false;
        }
        assertTrue(ok && success);
    }
}

contract StrictToken {
    address public immutable whale;
    constructor(address w) { whale = w; }
    function transfer(address to, uint256 /*tokens*/) external returns (bool success) {
        require(to != whale, "to whale");
        return true;
    }
}
